# Build test piece masks relative to 7x7 core, specials
pieces={}
# 2 bbox core exactly
m2=['1101111','1111111','1111111','0001111','1111111','1111111','1111111']
pieces['2']={(r,c) for r,row in enumerate(m2) for c,x in enumerate(row) if x=='1'}
# 3 core, hole col3 rows4-6; external left tab row3
m3=['1111111','1111111','1111111','1111111','1110111','1110111','1110111']
pieces['3']={(r,c) for r,row in enumerate(m3) for c,x in enumerate(row) if x=='1'} | {(3,-3),(3,-2),(3,-1)}
#7 core with notch row3 c0,1 and marker bottom right; stem upward
m7=['1111111','1111111','1111111','0011111','1111111','1111111','1111111']
pieces['7']={(r,c) for r,row in enumerate(m7) for c,x in enumerate(row) if x=='1'} | {(-1,3),(-2,3),(-3,3)}
# 8 core, tab right row3 + stem bottom c3
m8=['1111111']*7
pieces['8']={(r,c) for r,row in enumerate(m8) for c,x in enumerate(row) if x=='1'} | {(3,7),(7,3),(8,3)}
transforms={
'id':lambda r,c:(r,c), 'cw':lambda r,c:(c,6-r), '180':lambda r,c:(6-r,6-c), 'ccw':lambda r,c:(6-c,r),
'fh':lambda r,c:(r,6-c), 'fv':lambda r,c:(6-r,c), 'diag':lambda r,c:(c,r), 'anti':lambda r,c:(6-c,6-r)}
# marker of 7 in core at (6,6)
for n,f in transforms.items(): print(n,f(6,6))

m2=['1110111','1111111','1111111','0001111','1111111','1111111','1111111']
pieces['2']={(r,c) for r,row in enumerate(m2) for c,x in enumerate(row) if x=='1'}
sols=[]
for names in itertools.product(transforms, repeat=4):
    if transforms[names[0]](*orig_marker['7'])!=(0,0): continue
    occ={}; ok=True
    for name,(ro,co),tn in zip(orig_order,orig_offsets,names):
        f=transforms[tn]; cells={(f(r,c)[0]+ro,f(r,c)[1]+co) for r,c in pieces[name]}
        if any(r<0 or r>=14 or c<0 or c>=14 for r,c in cells) or cells & set(occ):ok=False;break
        for rc in cells:occ[rc]=name
    if ok: sols.append((names,{(r,c) for r in range(14) for c in range(14)}-set(occ),occ))
len(sols),[(x[0],len(x[1]),x[1]) for x in sols[:10]]

perms=[]
for order in itertools.permutations(['2','3','7','8']):
    if order[0]!='7': continue
    for names in itertools.product(transforms, repeat=4):
        if transforms[names[0]](*orig_marker['7'])!=(0,0): continue
        occ={};ok=True
        for name,(ro,co),tn in zip(order,orig_offsets,names):
            f=transforms[tn]; cells={(f(r,c)[0]+ro,f(r,c)[1]+co) for r,c in pieces[name]}
            if any(r<0 or r>=14 or c<0 or c>=14 for r,c in cells) or cells & set(occ):ok=False;break
            for rc in cells:occ[rc]=name
        if ok:perms.append((order,names,{(r,c) for r in range(14) for c in range(14)}-set(occ),occ))
len(perms),[(p[0],p[1],len(p[2])) for p in perms[:20]]

# Render intended solution: TL7(180), TR8(CW), BL3(180), BR2(identity)
assign=[('7','180',(0,0)),('8','cw',(0,7)),('3','180',(7,0)),('2','id',(7,7))]
grid=[[0]*14 for _ in range(14)]
for name,tn,(ro,co) in assign:
    f=transforms[tn]
    for r,c in pieces[name]:
        rr,cc=f(r,c); rr+=ro;cc+=co
        if not (0<=rr<14 and 0<=cc<14): print('OOB',name,rr,cc)
        if grid[rr][cc]!=0: print('overlap',name,rr,cc,grid[rr][cc])
        grid[rr][cc]=name
# replace marker 7 cell (transformed to TL) with 5
# above grid stores string names; set special
# check full and print
for row in grid: print(' '.join(row))
print('cells',sum(x!=0 for row in grid for x in row), 'blanks',[(r,c) for r in range(14) for c in range(14) if grid[r][c]==0])
